    }
    double avgImproved = improvedSum / TRIALS;

    std::cout << std::endl;
    std::cout << "=== Summary (averaged over " << TRIALS << " trials) ===" << std::endl;
    std::cout << "std::sort:               " << std::fixed << std::setprecision(4) << avgStdSort << " s" << std::endl;
    std::cout << "Naive Custom QuickSort:  " << std::fixed << std::setprecision(4) << avgNaive << " s" << std::endl;
    std::cout << "Improved Custom QuickSort: " << std::fixed << std::setprecision(4) << avgImproved << " s" << std::endl;
    std::cout << std::endl;
    std::cout << "Speedup vs Naive:        " << std::fixed << std::setprecision(2) << (avgNaive / avgStdSort) << "x" << std::endl;
    std::cout << "Speedup vs Improved:     " << std::fixed << std::setprecision(2) << (avgImproved / avgStdSort) << "x" << std::endl;

    return 0;
}
```

### Compilation & Execution

```bash
g++ -O3 -std=c++17 -march=native benchmark_sort.cpp -o benchmark_sort
./benchmark_sort
```

---

## Typical Empirical Results

Running the above benchmark on a modern machine (e.g., Intel Core i7-12700K, 32 GB RAM, Linux, GCC 11+) yields results like:

```
=== Sorting 10000000 doubles uniformly distributed on [0,1) ===

--- std::sort ---
